-- SPEC-005 review fix (2026-11-11): rows written before outbox.seq keep their record order.
-- 0005_cross_references.sql added seq as an identity, which numbered the rows already there in physical order,
-- not in each record's order. Give the unrelayed ones of those rows their own seq values again,
-- in the order the relay used before (subject, record version, occurred_at, id). Rows written since
-- keep theirs, so every old row still goes before every new one. Append-only: do not edit once applied.

-- The migrator has no BYPASSRLS and the outbox forces RLS: lift it for the backfill (as 0003 does),
-- or the UPDATE sees no workspace's rows. An ALWAYS identity cannot be updated: BY DEFAULT meanwhile.
ALTER TABLE subscriptions.outbox NO FORCE ROW LEVEL SECURITY;
ALTER TABLE subscriptions.outbox ALTER COLUMN seq SET GENERATED BY DEFAULT;

WITH old AS (
    SELECT id, seq,
           row_number() OVER (
               ORDER BY subject, coalesce((payload->>'version')::bigint, 0), occurred_at, id
           ) AS place
    FROM subscriptions.outbox
    WHERE relayed_at IS NULL
      AND occurred_at < (
          SELECT applied_at FROM public.schema_migrations WHERE name = '0005_cross_references.sql'
      )
), slots AS (
    SELECT seq, row_number() OVER (ORDER BY seq) AS place FROM old
)
UPDATE subscriptions.outbox o SET seq = slots.seq
FROM old JOIN slots USING (place)
WHERE o.id = old.id AND o.seq IS DISTINCT FROM slots.seq;

ALTER TABLE subscriptions.outbox ALTER COLUMN seq SET GENERATED ALWAYS;
ALTER TABLE subscriptions.outbox FORCE ROW LEVEL SECURITY;
